test("only the final standalone report controls stopping; examples, quotes, fences and duplicate tails cannot impersonate it", () => {
	const examples = "Example: WORK_STATUS: continue\n\n```text\nWORK_STATUS: blocked\n```\n\n> WORK_STATUS: continue\n\nFinished.\nWORK_STATUS: done";
	assert.equal(countWorkStatus(examples), 1);
	assert.equal(extractWorkStatus(examples), "done");
	for (const source of [
		"```\nWORK_STATUS: done\n```",
		"~~~text\nWORK_STATUS: done\n~~~",
		"> WORK_STATUS: done",
		"    WORK_STATUS: done",
		"Example: WORK_STATUS: done",
		"WORK_STATUS: done\nNot finished."
	]) assert.equal(parseWorkReport(source), null, source);
	assert.equal(parseWorkReport("WORK_STATUS: continue\n\nWORK_STATUS: done"), null);
	assert.equal(extractWorkStatus("WORK_STATUS: done\n<oai-mem-citation>metadata</oai-mem-citation>"), "done");
	assert.deepEqual(validateWorkReport(parseWorkReport("WORK_STATUS: blocked")), {
		protocolVersion: 2,
		status: "blocked",
		reason: "unknown"
	});
	assert.equal(validateWorkReport(parseWorkReport("WORK_STATUS: blocked | Waiting for a decision")).reason, "Waiting for a decision");
});
