test("invalid reports and completion failures share the same budget as ordinary continuation", () => {
	const f = fixture();
	try {
		for (let index = 0; index < 20; index++) {
			const text = index % 3 === 0 ? "WORK_STATUS: continue" : index % 3 === 1 ? "WORK_STATUS: done" : "Missing report";
			const input = {
				...f.input,
				statusEmissionId: `response-${index}`,
				lastAssistantMessage: text
			};
			const result = evaluateStopPolicy(input, {
				root: f.root,
				runCheck: () => ({
					ok: false,
					output: `Unverified evidence ${index}`
				})
			});
			assert.equal(result.shouldDeliver, true, `round ${index}`);
			assert.equal(evaluateStopPolicy(input, { root: f.root }).shouldDeliver, false, "a hook retry cannot deliver twice");
		}
		const limited = evaluateStopPolicy({
			...f.input,
			statusEmissionId: "round-21",
			lastAssistantMessage: "WORK_STATUS: continue"
		}, { root: f.root });
		assert.equal(limited.disposition, "pause_for_human");
		assert.equal(limited.shouldDeliver, false);
		assert.equal(readSessionState(f.root, "codex", "work")?.autonomousChainCount, 20);
	} finally {
		f.clean();
	}
});
