test("automatic continuation evidence needs the matching receipt in the same session and user turn", () => {
	for (const mode of [
		"unrelated",
		"new-user-turn",
		"wrong-request",
		"confirmed"
	]) {
		const f = fixture();
		try {
			const stop = {
				...f.input,
				product: "codebuddy",
				userTurnId: "user-1",
				lastAssistantMessage: "WORK_STATUS: continue"
			};
			initializeSessionState(f.root, stop);
			recordUserTurn(f.root, stop);
			beginVerificationRun(f.root, "codebuddy", {
				verificationRunId: mode,
				hostVersion: "fixture-1"
			});
			const result = evaluateStopPolicy(stop, { root: f.root });
			appendVerificationEvent(f.root, stop, { decision: result });
			const next = {
				...stop,
				event: "assistant_response",
				eventId: "delivery",
				userTurnId: null,
				lastAssistantMessage: null,
				continuationRequestId: mode === "unrelated" ? null : mode === "wrong-request" ? "wrong" : result.continuationRequestId,
				userInitiated: mode === "new-user-turn"
			};
			observeHarnessEvent(f.root, next);
			appendVerificationEvent(f.root, next, { observations: ["automatic_continuation"] });
			const observed = verifyRuntimeEvidence(f.root, "codebuddy", { verificationRunId: mode });
			assert.equal(observed.capabilities?.automatic_continuation.result, mode === "confirmed" ? "passed" : "not_tested", mode);
		} finally {
			f.clean();
		}
	}
});
